WITH cleaned AS (SELECT id, plan, start_date, end_date, DATEDIFF(start_date, end_date) AS days_end_date_to_start_date FROM subscriptions WHERE customer_id IS NOT NULL), cleaned_subscriptions AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title, DATE_FORMAT(end_date, 'yyyy-MM-dd') AS end_date_label FROM cleaned WHERE end_date > DATE '2023-05-26'), valid AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title_2 FROM cleaned_subscriptions WHERE end_date > '2025-10-18'), latest AS (SELECT * FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY plan ORDER BY start_date NULLS FIRST, id) = 1) SELECT DATE_TRUNC('WEEK', start_date) AS week_start, plan, COUNT(*) FILTER (WHERE plan = 'standard') AS standard_rows, ROUND(AVG(days_end_date_to_start_date), 2) AS avg_days_end_date_to_start_date, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count FROM latest GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', start_date), plan), (DATE_TRUNC('WEEK', start_date)));
